SELECT CONCAT('INSERT INTO ps_product_supplier (`id_product_supplier`,`id_product`,`id_product_attribute`,`id_supplier`,`product_supplier_reference`,`product_supplier_price_te`,`id_currency`) VALUES (', QUOTE(o.`id_product_supplier`), ',', QUOTE(o.`id_product`), ',', QUOTE(o.`id_product_attribute`), ',', QUOTE(o.`id_supplier`), ',', QUOTE(o.`product_supplier_reference`), ',', QUOTE(o.`product_supplier_price_te`), ',', QUOTE(o.`id_currency`), ') ON DUPLICATE KEY UPDATE `id_product_supplier`=VALUES(`id_product_supplier`),`id_product`=VALUES(`id_product`),`id_product_attribute`=VALUES(`id_product_attribute`),`id_supplier`=VALUES(`id_supplier`),`product_supplier_reference`=VALUES(`product_supplier_reference`),`product_supplier_price_te`=VALUES(`product_supplier_price_te`),`id_currency`=VALUES(`id_currency`);') AS q FROM ps_product_supplier o WHERE o.id_product IN (SELECT p2.id_product FROM ps_product p2 WHERE p2.date_upd >= '2026-09-01')
UNION
SELECT CONCAT('INSERT INTO ps_supplier (`id_supplier`,`name`,`date_add`,`date_upd`,`active`) VALUES (', QUOTE(o.`id_supplier`), ',', QUOTE(o.`name`), ',', QUOTE(o.`date_add`), ',', QUOTE(o.`date_upd`), ',', QUOTE(o.`active`), ') ON DUPLICATE KEY UPDATE `id_supplier`=VALUES(`id_supplier`),`name`=VALUES(`name`),`date_add`=VALUES(`date_add`),`date_upd`=VALUES(`date_upd`),`active`=VALUES(`active`);') AS q FROM ps_supplier o WHERE o.id_supplier > 0